                           $ear_plug, $tgl_ear_plug]) {

            $emp = Employee::whereRaw('UPPER(TRIM(nama_lengkap)) = ?', [strtoupper(trim($name))])->first();

            if (!$emp) {
                $parts = explode(' ', strtoupper(trim($name)));
                if (count($parts) >= 2) {
                    $emp = Employee::whereRaw(
                        'UPPER(nama_lengkap) LIKE ?',
                        [$parts[0] . '%' . $parts[1] . '%']
                    )->first();
                }
            }

            if (!$emp) { $notFound[] = $name; continue; }

            Ppe::updateOrCreate(
                ['employee_id' => $emp->id],
                array_filter([
                    'frc'          => $frc,
                    'safety_shoes' => $shoes,
                    'tgl_frc'      => $tgl_frc,
                    'tgl_frc_2'    => $tgl_frc_2,
